/**
 * Shapes the OpenAPI document (openapi.json, generated by `go run ./cmd/openapi`
 * in BE and checked equal to the backend's copy by its tests) into the data the
 * API reference page renders. Nothing here is written by hand: operations,
 * scopes, fields and the guide all come from the document.
 */

export interface TypePart {
	text: string;
	/** Name of a schema this part links to. */
	ref?: string;
}

export interface ApiField {
	name: string;
	required: boolean;
	type: TypePart[];
	notes: string;
}

export interface ApiSchema {
	name: string;
	fields: ApiField[];
}

export interface ApiParameter {
	name: string;
	in: string;
	required: boolean;
	type: TypePart[];
	description: string;
}

export interface ApiOperation {
	id: string;
	method: string;
	path: string;
	summary: string;
	description: string;
	scopes: string[];
	parameters: ApiParameter[];
	request: TypePart[] | null;
	status: string;
	response: TypePart[];
	errors: string[];
}

export interface ApiGroup {
	name: string;
	anchor: string;
	description: string;
	operations: ApiOperation[];
}

export interface GuideSection {
	id: string;
	title: string;
	paragraphs: string[];
	list?: string[];
	code?: { language: string; text: string };
}

export interface ApiReference {
	title: string;
	summary: string;
	guide: GuideSection[];
	groups: ApiGroup[];
	schemas: ApiSchema[];
	operationCount: number;
	webhook: { signatureHeader: string; eventHeader: string; body: TypePart[] } | null;
}

type Json = Record<string, any>;

const METHODS = ['get', 'post', 'put', 'patch', 'delete'];

export function schemaAnchor(name: string): string {
	return `schema-${name}`;
}

function refName(ref: string): string {
	return ref.slice(ref.lastIndexOf('/') + 1);
}

/** Describes a schema as readable parts, linking named schemas. */
export function describeType(schema: Json | undefined): TypePart[] {
	if (!schema) return [{ text: 'any' }];
	if (schema.$ref) {
		const name = refName(schema.$ref);
		return [{ text: name, ref: name }];
	}
	if (Array.isArray(schema.anyOf)) {
		return schema.anyOf.flatMap((option: Json, index: number) => [
			...(index > 0 ? [{ text: ' or ' }] : []),
			...describeType(option)
		]);
	}
	const types: string[] = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : [];
	if (types.length === 0) return [{ text: 'any JSON value' }];
	if (types.length === 1 && types[0] === 'null') return [{ text: 'null' }];
	const nullable = types.includes('null');
	const base = types.find((type) => type !== 'null') ?? 'null';
	let parts: TypePart[];
	if (base === 'array') {
		parts = [{ text: 'array of ' }, ...describeType(schema.items)];
	} else if (base === 'object' && schema.additionalProperties) {
		parts = [{ text: 'map of ' }, ...describeType(schema.additionalProperties)];
	} else {
		parts = [{ text: schema.format ? `${base} (${schema.format})` : base }];
	}
	return nullable ? [...parts, { text: ' or null' }] : parts;
}

/** Lists the constraints generated from the backend's validation rules. */
export function describeConstraints(schema: Json | undefined): string {
	if (!schema) return '';
	const target = schema.type === 'array' && schema.items && !schema.items.$ref ? { ...schema.items, ...schema, enum: schema.items.enum } : schema;
	const notes: string[] = [];
	if (Array.isArray(target.enum)) notes.push(`one of ${target.enum.join(', ')}`);
	if (target.minLength !== undefined || target.maxLength !== undefined) {
		notes.push(`length ${target.minLength ?? 0} to ${target.maxLength ?? 'any'}`);
	}
	if (target.minimum !== undefined || target.maximum !== undefined) {
		notes.push(`${target.minimum ?? 'any'} to ${target.maximum ?? 'any'}`);
	}
	if (target.minItems !== undefined) notes.push(`at least ${target.minItems} item${target.minItems === 1 ? '' : 's'}`);
	if (target.maxItems !== undefined) notes.push(`at most ${target.maxItems} items`);
	return notes.join('; ');
}

function slug(text: string): string {
	return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export function buildApiReference(spec: Json): ApiReference {
	const groups = new Map<string, ApiGroup>();
	for (const tag of spec.tags ?? []) {
		groups.set(tag.name, { name: tag.name, anchor: `endpoints-${slug(tag.name)}`, description: tag.description ?? '', operations: [] });
	}

	let operationCount = 0;
	for (const [path, item] of Object.entries<Json>(spec.paths ?? {})) {
		for (const method of METHODS) {
			const operation: Json | undefined = item[method];
			// Only operations marked stable are published; the document holds no others.
			if (!operation || operation['x-kuayle-stability'] !== 'stable') continue;
			const group = groups.get(operation.tags?.[0]);
			if (!group) throw new Error(`${operation.operationId} has no known tag`);

			const statuses = Object.keys(operation.responses ?? {}).sort();
			const success = statuses.find((status) => status.startsWith('2'));
			if (!success) throw new Error(`${operation.operationId} documents no success response`);
			const scopes: string[] = operation['x-kuayle-scopes'] ?? [];

			group.operations.push({
				id: operation.operationId,
				method: method.toUpperCase(),
				path,
				summary: operation.summary ?? '',
				// The scope sentence is rendered from x-kuayle-scopes instead.
				description: String(operation.description ?? '').replace(/\n*Required scope: .*$/s, ''),
				scopes,
				parameters: (operation.parameters ?? []).map((parameter: Json) => ({
					name: parameter.name,
					in: parameter.in,
					required: parameter.required === true,
					type: describeType(parameter.schema),
					description: [parameter.description, describeConstraints(parameter.schema)].filter(Boolean).join(' ')
				})),
				request: operation.requestBody ? describeType(operation.requestBody.content?.['application/json']?.schema) : null,
				status: success,
				response: describeType(operation.responses[success].content?.['application/json']?.schema),
				errors: statuses.filter((status) => !status.startsWith('2'))
			});
			operationCount += 1;
		}
	}

	const schemas: ApiSchema[] = Object.entries<Json>(spec.components?.schemas ?? {})
		.sort(([a], [b]) => a.localeCompare(b))
		.map(([name, schema]) => ({
			name,
			fields: Object.entries<Json>(schema.properties ?? {}).map(([field, definition]) => ({
				name: field,
				required: (schema.required ?? []).includes(field),
				type: describeType(definition),
				notes: describeConstraints(definition)
			}))
		}));

	const delivery: Json | undefined = spec.webhooks?.delivery?.post;
	const headers: Json[] = delivery?.parameters ?? [];

	return {
		title: spec.info?.title ?? 'API',
		summary: spec.info?.summary ?? '',
		guide: spec['x-kuayle-guide'] ?? [],
		groups: [...groups.values()].filter((group) => group.operations.length > 0),
		schemas,
		operationCount,
		webhook: delivery
			? {
					signatureHeader: headers[0]?.name ?? '',
					eventHeader: headers[1]?.name ?? '',
					body: describeType(delivery.requestBody?.content?.['application/json']?.schema)
				}
			: null
	};
}
